        R = 1.0D0
        D1MACH = R * 1.7976931348623157D308
      ELSE IF (I .EQ. 5) THEN
        D1MACH = 2.2250738585072014D-308
      ELSE IF (I .EQ. 6) THEN
        D1MACH = 2.2204460492503131D-16
      ELSE
